insert into public.interaction_pairs (group_a, group_b, description, source, verified_on)
values
  ('B01AA', 'B01AC', 'Antagoniści witaminy K (np. acenokumarol, warfaryna) i leki przeciwpłytkowe (np. kwas acetylosalicylowy, klopidogrel) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Acenocumarol WZF (acenokumarol) pkt 4.5', '2026-09-24'::date),
  ('B01AA', 'M01AB', 'Antagoniści witaminy K (np. acenokumarol, warfaryna) i leki przeciwbólowe z grupy diklofenaku mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Acenocumarol WZF (acenokumarol) pkt 4.5', '2026-09-24'::date),
  ('B01AA', 'M01AE', 'Antagoniści witaminy K (np. acenokumarol, warfaryna) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Acenocumarol WZF (acenokumarol) pkt 4.5', '2026-09-24'::date),
  ('B01AA', 'N06AB', 'Antagoniści witaminy K (np. acenokumarol, warfaryna) i leki przeciwdepresyjne z grupy SSRI (np. sertralina, escytalopram) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Zoloft (sertralina) pkt 4.5', '2026-09-24'::date),
  ('B01AC', 'B01AF', 'Leki przeciwpłytkowe (np. kwas acetylosalicylowy, klopidogrel) i leki przeciwkrzepliwe z grupy rywaroksabanu i apiksabanu mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Xarelto (rywaroksaban) pkt 4.5', '2026-09-24'::date),
  ('B01AC', 'M01AE', 'Leki przeciwpłytkowe (np. kwas acetylosalicylowy, klopidogrel) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień, a przy kwasie acetylosalicylowym także ze słabszym jego działaniem przeciwpłytkowym.', 'ChPL Ibuprom (ibuprofen) pkt 4.5', '2026-09-24'::date),
  ('B01AC', 'N06AB', 'Leki przeciwpłytkowe (np. kwas acetylosalicylowy, klopidogrel) i leki przeciwdepresyjne z grupy SSRI (np. sertralina, escytalopram) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Zoloft (sertralina) pkt 4.5', '2026-09-24'::date),
  ('B01AF', 'M01AE', 'Leki przeciwkrzepliwe z grupy rywaroksabanu i apiksabanu oraz leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Xarelto (rywaroksaban) pkt 4.5', '2026-09-24'::date),
  ('B01AF', 'N06AB', 'Leki przeciwkrzepliwe z grupy rywaroksabanu i apiksabanu oraz leki przeciwdepresyjne z grupy SSRI (np. sertralina, escytalopram) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z łatwiejszym powstawaniem krwawień i siniaków.', 'ChPL Xarelto (rywaroksaban) pkt 4.5', '2026-09-24'::date),
  ('C03AA', 'M01AE', 'Tiazydowe leki moczopędne (np. hydrochlorotiazyd) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym działaniem moczopędnym i słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek.', 'ChPL Hydrochlorothiazidum Polpharma (hydrochlorotiazyd) pkt 4.5', '2026-09-24'::date),
  ('C03CA', 'C09AA', 'Pętlowe leki moczopędne (np. furosemid) i inhibitory ACE (np. ramipryl, perindopryl) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z niższym ciśnieniem krwi, zwłaszcza w pierwszych dniach przyjmowania obu leków.', 'ChPL Tritace (ramipryl) pkt 4.5', '2026-09-24'::date),
  ('C03CA', 'M01AE', 'Pętlowe leki moczopędne (np. furosemid) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym działaniem moczopędnym i słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek.', 'ChPL Furosemidum Polpharma (furosemid) pkt 4.5', '2026-09-24'::date),
  ('C07AB', 'C08CA', 'Wybiórcze beta-blokery (np. bisoprolol, metoprolol) i leki z grupy amlodypiny (pochodne dihydropirydyny) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z niższym ciśnieniem krwi.', 'ChPL Concor (bisoprolol) pkt 4.5', '2026-09-24'::date),
  ('C08CA', 'C10AA', 'Leki z grupy amlodypiny (pochodne dihydropirydyny) i statyny (np. symwastatyna, atorwastatyna) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z wyższym stężeniem niektórych statyn we krwi i z dolegliwościami mięśniowymi.', 'ChPL Norvasc (amlodypina) pkt 4.5', '2026-09-24'::date),
  ('C09AA', 'C09CA', 'Inhibitory ACE (np. ramipryl, perindopryl) i sartany (np. walsartan, losartan) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z niższym ciśnieniem krwi oraz ze zmianami czynności nerek i stężenia potasu we krwi.', 'ChPL Diovan (walsartan) pkt 4.5', '2026-09-24'::date),
  ('C09AA', 'M01AB', 'Inhibitory ACE (np. ramipryl, perindopryl) i leki przeciwbólowe z grupy diklofenaku mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek i stężenia potasu we krwi.', 'ChPL Tritace (ramipryl) pkt 4.5', '2026-09-24'::date),
  ('C09AA', 'M01AE', 'Inhibitory ACE (np. ramipryl, perindopryl) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek i stężenia potasu we krwi.', 'ChPL Tritace (ramipryl) pkt 4.5', '2026-09-24'::date),
  ('C09AA', 'N05AN', 'Inhibitory ACE (np. ramipryl, perindopryl) i lit mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z wyższym stężeniem litu we krwi.', 'ChPL Tritace (ramipryl) pkt 4.5', '2026-09-24'::date),
  ('C09CA', 'M01AB', 'Sartany (np. walsartan, losartan) i leki przeciwbólowe z grupy diklofenaku mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek i stężenia potasu we krwi.', 'ChPL Diovan (walsartan) pkt 4.5', '2026-09-24'::date),
  ('C09CA', 'M01AE', 'Sartany (np. walsartan, losartan) i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek ze słabszym obniżeniem ciśnienia oraz ze zmianami czynności nerek i stężenia potasu we krwi.', 'ChPL Diovan (walsartan) pkt 4.5', '2026-09-24'::date),
  ('C09CA', 'N05AN', 'Sartany (np. walsartan, losartan) i lit mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z wyższym stężeniem litu we krwi.', 'ChPL Diovan (walsartan) pkt 4.5', '2026-09-24'::date),
  ('M01AB', 'M01AE', 'Leki przeciwbólowe z grupy diklofenaku i leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z dolegliwościami żołądka i krwawieniem z przewodu pokarmowego.', 'ChPL Ibuprom (ibuprofen) pkt 4.5', '2026-09-24'::date),
  ('M01AE', 'M01AE', 'Dwa leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen i ketoprofen) przyjmowane w tym samym czasie mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z dolegliwościami żołądka i krwawieniem z przewodu pokarmowego.', 'ChPL Ibuprom (ibuprofen) pkt 4.5', '2026-09-24'::date),
  ('M01AE', 'N06AB', 'Leki przeciwbólowe z grupy ibuprofenu (np. ibuprofen, naproksen) i leki przeciwdepresyjne z grupy SSRI (np. sertralina, escytalopram) mogą wchodzić w interakcję. Jednoczesne przyjmowanie może mieć związek z krwawieniem z przewodu pokarmowego.', 'ChPL Zoloft (sertralina) pkt 4.5', '2026-09-24'::date)
on conflict (group_a, group_b) do nothing;
